'use strict';
const {TYPES,ports,getPort,fits,canConnect,validate,parse,exampleName}=DIN;
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''), colors={L:'#7b523c',L1:'#7b523c',L2:'#303e46',L3:'#8a9398',N:'#2f8cc6',PE:'#61a33a'};
const fresh=()=>({version:1,name:'Rozdzielnia domu',components:[],wires:[],circuits:[]});
function demo(){let s=fresh();const add=(type,label,row,slot)=>s.components.push({id:uid(),type,label,row,slot,rating:TYPES[type].rating,on:true});add('MAIN','Q0',0,0);add('SPD','SPD1',0,5);add('PE','PE1',0,14);add('RCD','RCD1',1,0);add('MCB','F1',1,5);add('MCB','F2',1,7);add('MCB','F3',1,9);add('N','N1',1,14);add('RCBO','F4',2,0);s.circuits=['Oświetlenie parteru','Gniazda salonu','Gniazda kuchni','Lodówka'].map((name,i)=>({id:uid(),name,device:s.components[[4,5,6,8][i]].id,power:[300,1500,2200,250][i],cable:i?'3 × 2,5':'3 × 1,5'}));s.components[4].rating='B10';return s;}
let state=demo(),selected=null,pending=null,mode='select',showWires=true,checked=false,history=[],future=[],drag=null;
try{const saved=localStorage.getItem('din-studio-v1');if(saved)state=parse(JSON.parse(saved));}catch(e){console.warn('Nie odtworzono projektu',e.message)}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3000)}
function persist(){try{localStorage.setItem('din-studio-v1',JSON.stringify(state));return true}catch(e){toast('Zapis lokalny niedostępny. Wyeksportuj JSON.');return false}}
function change(fn){history.push(JSON.stringify(state));if(history.length>80)history.shift();future=[];fn();persist();render()}
function restore(from,to){if(!from.length)return;to.push(JSON.stringify(state));state=JSON.parse(from.pop());selected=null;pending=null;persist();render()}
function hint(t){$('hint').textContent=t|| (pending?'Wybierz drugi zacisk. Esc anuluje połączenie.':mode==='wire'?'Kliknij pierwszy i drugi zacisk, aby dodać przewód. Parametry zmienisz w panelu po prawej.':'Przeciągnij aparat z katalogu. Kliknij element, aby edytować jego parametry.')}
function setMode(m){mode=m;pending=null;$('selectMode').classList.toggle('active',m==='select');$('wireMode').classList.toggle('active',m==='wire');render()}
$('catalog').innerHTML=Object.entries(TYPES).map(([key,t])=>`<button class="catalog-item" draggable="false" data-type="${key}" title="${esc(t.name)}${t.example?' · przykład: '+esc(exampleName(key)):''}"><span class="mini-device"></span><span><strong>${t.short}</strong><small>${t.name}</small><small>${t.width} mod.</small>${t.example?`<small class="example">np. ${esc(t.example.series+' '+t.example.name)}</small>`:''}</span></button>`).join('');
$('catalog').addEventListener('dragstart',e=>{const el=e.target.closest('[data-type]');if(!el)return;drag={type:el.dataset.type};e.dataTransfer.setData('text/plain',el.dataset.type);e.dataTransfer.effectAllowed='copy'});
$('catalog').addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const el=e.target.closest('[data-type]');if(!el)return;const c=makeComponent(el.dataset.type);for(let row=0;row<4;row++)for(let slot=0;slot<18;slot++)if(fits(state,c,row,slot)){change(()=>{c.row=row;c.slot=slot;state.components.push(c);selected={kind:'device',id:c.id}});return}toast('Brak miejsca na ten aparat.')});

// Pointer dragging works with mouse, pen and touch, including browsers without native HTML drag.
let pointerDrag=null, suppressClickUntil=0;
function beginPointerDrag(e,source){
 if(e.button!==0)return;
 const target=e.target.closest(source==='palette'?'[data-type]':'.device');
 if(!target||(source==='device'&&(mode!=='select'||e.target.closest('button'))))return;
 const box=target.getBoundingClientRect();
 pointerDrag={pointerId:e.pointerId,startX:e.clientX,startY:e.clientY,source,
  id:source==='device'?target.dataset.id:null,type:target.dataset.type,
  offsetX:source==='device'?e.clientX-box.left:20,
  offsetY:source==='device'?e.clientY-box.top:49,moved:false,ghost:null};
 target.setPointerCapture(e.pointerId);
}
$('catalog').addEventListener('pointerdown',e=>beginPointerDrag(e,'palette'));
$('components').addEventListener('pointerdown',e=>beginPointerDrag(e,'device'));
document.addEventListener('pointermove',e=>{
 const d=pointerDrag;if(!d||d.pointerId!==e.pointerId)return;
 if(!d.moved&&Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<5)return;
 e.preventDefault();
 if(!d.moved){d.moved=true;d.ghost=document.createElement('div');d.ghost.className='drag-ghost';d.ghost.textContent=d.id?state.components.find(c=>c.id===d.id).label:TYPES[d.type].short;d.ghost.style.width=(TYPES[d.type].width*40-4)+'px';document.body.appendChild(d.ghost);$('board').classList.add('drag-active');}
 d.ghost.style.left=(e.clientX-d.offsetX)+'px';d.ghost.style.top=(e.clientY-d.offsetY)+'px';
},{passive:false});
function finishPointerDrag(e,cancel){
 const d=pointerDrag;if(!d||d.pointerId!==e.pointerId)return;pointerDrag=null;d.ghost?.remove();$('board').classList.remove('drag-active');
 if(!d.moved)return;suppressClickUntil=Date.now()+400;
 if(cancel)return;e.preventDefault();
 const b=$('board').getBoundingClientRect();
 const row=Math.round((e.clientY-d.offsetY-b.top-67)/137),slot=Math.round((e.clientX-d.offsetX-b.left-25)/40);
 const c=d.id?state.components.find(c=>c.id===d.id):makeComponent(d.type);
 if(!c||e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom||!fits(state,c,row,slot)){toast('To miejsce jest zajęte lub poza szyną.');return;}
 change(()=>{c.row=row;c.slot=slot;if(!d.id)state.components.push(c);selected={kind:'device',id:c.id}});
}
document.addEventListener('pointerup',e=>finishPointerDrag(e,false));
document.addEventListener('pointercancel',e=>finishPointerDrag(e,true));

function makeComponent(type){const n=state.components.filter(c=>c.type===type).length+1;return{id:uid(),type,label:TYPES[type].short+n,row:0,slot:0,rating:TYPES[type].rating,on:true}}
$('board').addEventListener('dragover',e=>e.preventDefault());
$('board').addEventListener('drop',e=>{e.preventDefault();if(!drag)return;const b=$('board').getBoundingClientRect(),row=Math.round((e.clientY-b.top-67)/137),slot=Math.floor((e.clientX-b.left-25)/40);const c=drag.id?state.components.find(c=>c.id===drag.id):makeComponent(drag.type);drag=null;if(!c||!fits(state,c,row,slot)){toast('To miejsce jest zajęte lub poza szyną.');return}change(()=>{c.row=row;c.slot=slot;if(!state.components.some(x=>x.id===c.id))state.components.push(c);selected={kind:'device',id:c.id}})});
$('components').addEventListener('dragstart',e=>{if(e.target.closest('button')){e.preventDefault();return}const el=e.target.closest('.device');if(!el)return;drag={id:el.dataset.id};e.dataTransfer.setData('text/plain',el.dataset.id);e.dataTransfer.effectAllowed='move'});
$('components').addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const el=e.target.closest('.device');if(!el)return;const id=el.dataset.id,term=e.target.closest('.terminal');if(term){connect({device:id,port:term.dataset.port});return}if(e.target.closest('.lever')){change(()=>{const c=state.components.find(c=>c.id===id);c.on=!c.on;selected={kind:'device',id}});return}selected={kind:'device',id};render()});
function connect(end){if(!pending){pending=end;hint();renderBoard();return}if(pending.device===end.device&&pending.port===end.port){pending=null;render();return}const error=canConnect(state,pending,end);if(error){toast(error);return}const a={...pending},role=getPort(state,a).role;change(()=>{const w={id:uid(),a,b:end,role,gauge:2.5};state.wires.push(w);selected={kind:'wire',id:w.id};pending=null});}
function coord(end){const c=state.components.find(c=>c.id===end.device),p=getPort(state,end);return{x:25+c.slot*40+((p.i+.5)/p.count)*(TYPES[c.type].width*40-4),y:67+c.row*137+(p.side==='t'?9:90)}}
function renderBoard(){
$('rails').innerHTML=Array.from({length:4},(_,i)=>`<div class="rail" style="top:${58+i*137}px"><span class="rail-label">RZĄD ${String(i+1).padStart(2,'0')}</span><div class="slotnums">${Array.from({length:18},(_,j)=>`<span>${j+1}</span>`).join('')}</div></div>`).join('');
$('components').innerHTML=state.components.map(c=>{const t=TYPES[c.type],lever=!['SPD','N','PE'].includes(c.type),ex=exampleName(c.type);return `<div class="device ${selected?.kind==='device'&&selected.id===c.id?'selected':''}" data-id="${c.id}" data-type="${c.type}" data-w="${t.width}" draggable="false" style="left:${25+c.slot*40}px;top:${67+c.row*137}px;width:${t.width*40-4}px" title="${esc(c.label)} · ${esc(t.name)}${ex?' · przykład typu (poglądowo): '+esc(ex):''}"><span class="devlabel">${esc(c.label)}</span><span class="devrating">${esc(c.rating)}</span>${lever?`<button class="lever ${c.on?'':'off'}" title="${c.on?'Wyłącz':'Włącz'} aparat w modelu" aria-label="${c.on?'Wyłącz':'Włącz'} ${esc(c.label)}"></button>`:''}${['RCD','RCBO'].includes(c.type)?'<span class="testbtn" aria-hidden="true">T</span>':''}${c.type==='SPD'?`<span class="cartridges" aria-hidden="true">${t.poles.map(()=>'<i></i>').join('')}</span>`:''}${['N','PE'].includes(c.type)?'<span class="busbar" aria-hidden="true"></span>':''}<span class="devtype">${lever?`<i class="st ${c.on?'on':'off'}">${c.on?'I':'O'}</i>`:''}${t.short}</span>${ports(c).map(p=>`<button class="terminal ${p.side==='t'?'top':'bottom'} ${pending?.device===c.id&&pending.port===p.key?'pending':''}" data-port="${p.key}" style="left:${(p.i+.5)/p.count*100}%" title="${esc(c.label)}: ${p.side==='t'?'góra':'dół'} ${p.role} (${p.i+1})" aria-label="Zacisk ${esc(c.label)} ${p.key} ${p.role}"><span>${p.role}</span></button>`).join('')}</div>`}).join('');
$('wires').style.display=showWires?'block':'none';$('wires').innerHTML=state.wires.map((w,i)=>{const a=coord(w.a),b=coord(w.b),mid=(a.y+b.y)/2+(i%4)*6;const d=`M ${a.x} ${a.y} V ${mid} H ${b.x} V ${b.y}`;return `<path class="wire-hit" data-wire="${w.id}" d="${d}"/><path class="wire ${selected?.kind==='wire'&&selected.id===w.id?'selected':''}" data-wire="${w.id}" d="${d}" stroke="${colors[w.role]}" ${w.role==='PE'?'stroke-dasharray="9 3"':''}/>`}).join('');
}
$('wires').addEventListener('click',e=>{const id=e.target.dataset.wire;if(id){selected={kind:'wire',id};render()}});
function renderInspector(){const c=selected?.kind==='device'&&state.components.find(c=>c.id===selected.id),w=selected?.kind==='wire'&&state.wires.find(w=>w.id===selected.id);if(c){$('inspector').innerHTML=`<h2>${TYPES[c.type].name}</h2><div class="kv"><span>Typ / szerokość</span><b>${TYPES[c.type].short} / ${TYPES[c.type].width} mod.</b></div><label class="field">Oznaczenie<input id="editLabel" maxlength="60" value="${esc(c.label)}"></label><label class="field">Opis parametrów (bez obliczeń)<input id="editRating" maxlength="100" value="${esc(c.rating)}"></label><div class="kv"><span>Położenie</span><b>Rząd ${c.row+1} · moduł ${c.slot+1}</b></div><label class="field">Rząd<select id="editRow">${[0,1,2,3].map(r=>`<option value="${r}" ${c.row===r?'selected':''}>Rząd ${r+1}</option>`).join('')}</select></label><label class="field">Pierwszy moduł<input id="editSlot" type="number" min="1" max="18" value="${c.slot+1}"></label><button class="delete" id="deleteSelected">Usuń aparat i jego przewody</button>`;$('editLabel').onchange=e=>change(()=>c.label=e.target.value.trim()||TYPES[c.type].short);$('editRating').onchange=e=>change(()=>c.rating=e.target.value);const move=()=>{const row=+$('editRow').value,slot=+$('editSlot').value-1;if(!fits(state,c,row,slot)){toast('To miejsce nie jest dostępne.');renderInspector();return}change(()=>{c.row=row;c.slot=slot})};$('editRow').onchange=move;$('editSlot').onchange=move;
}else if(w){const label=e=>state.components.find(c=>c.id===e.device).label+' / '+getPort(state,e).role;$('inspector').innerHTML=`<h2>Połączenie przewodem</h2><div class="kv"><span>Od</span><b>${esc(label(w.a))}</b></div><div class="kv"><span>Do</span><b>${esc(label(w.b))}</b></div><label class="field">Funkcja i kolor żyły<select id="wireRole">${Object.keys(colors).map(r=>`<option ${w.role===r?'selected':''}>${r}</option>`).join('')}</select></label><label class="field">Przekrój [mm²]<select id="wireGauge">${[1.5,2.5,4,6,10,16].map(n=>`<option value="${n}" ${w.gauge===n?'selected':''}>${n}</option>`).join('')}</select></label><p class="muted" style="font-size:11px">Przekrój jest zapisanym parametrem. Prototyp nie oblicza jego obciążalności.</p><button class="delete" id="deleteSelected">Usuń przewód</button>`;$('wireRole').onchange=e=>change(()=>w.role=e.target.value);$('wireGauge').onchange=e=>change(()=>w.gauge=+e.target.value);
}else{$('inspector').innerHTML=`<div class="selection-empty"><div class="largeicon">⌖</div><h2>Przestrzeń do projektowania</h2><p>Zaznacz aparat lub przewód, aby zobaczyć i zmienić jego parametry.</p></div><div class="kv"><span>Aparaty</span><b>${state.components.length}</b></div><div class="kv"><span>Połączenia</span><b>${state.wires.length}</b></div><div class="kv"><span>Zapis</span><b>W tej przeglądarce</b></div>`}if($('deleteSelected'))$('deleteSelected').onclick=removeSelected;}
function removeSelected(){if(!selected)return;change(()=>{if(selected.kind==='device'){state.components=state.components.filter(c=>c.id!==selected.id);state.wires=state.wires.filter(w=>w.a.device!==selected.id&&w.b.device!==selected.id);state.circuits.forEach(c=>{if(c.device===selected.id)c.device=''})}else state.wires=state.wires.filter(w=>w.id!==selected.id);selected=null;pending=null})}
function renderCircuits(){$('circuitCount').textContent=String(state.circuits.length);$('circuitRows').innerHTML=state.circuits.map(c=>`<tr data-circuit="${c.id}"><td><input data-field="name" aria-label="Nazwa obwodu" value="${esc(c.name)}" maxlength="120"></td><td><select data-field="device" aria-label="Aparat obwodu"><option value="">Nie przypisano</option>${state.components.filter(x=>['MCB','RCBO'].includes(x.type)).map(x=>`<option value="${x.id}" ${c.device===x.id?'selected':''}>${esc(x.label)}</option>`).join('')}</select></td><td><input data-field="power" type="number" min="0" max="1000000" aria-label="Moc w watach" value="${c.power}"></td><td><input data-field="cable" aria-label="Opis przewodu" maxlength="60" value="${esc(c.cable)}"></td><td><button class="iconbtn" data-delete="${c.id}" title="Usuń obwód">×</button></td></tr>`).join('')}
$('circuitRows').addEventListener('change',e=>{const id=e.target.closest('tr')?.dataset.circuit,field=e.target.dataset.field;if(!id||!field)return;const value=field==='power'?Math.max(0,Math.min(1000000,Number(e.target.value)||0)):e.target.value;change(()=>state.circuits.find(c=>c.id===id)[field]=value)});
$('circuitRows').addEventListener('click',e=>{const id=e.target.dataset.delete;if(id)change(()=>state.circuits=state.circuits.filter(c=>c.id!==id))});
function renderChecks(){if(!checked)return;const issues=validate(state);const errors=issues.filter(i=>i.severity==='error').length;$('checks').innerHTML=`<div class="checksummary">${errors?'Wykryto '+errors+' konfliktów połączeń.':'Nie wykryto konfliktów w sprawdzanym zakresie.'}<br>${issues.length-errors} uwag do przejrzenia. Kontrola nie obejmuje RCD, obciążalności, selektywności ani zwarć.</div>`+issues.map((i,k)=>`<button class="issueitem ${i.severity}" data-issue="${k}"><strong>${esc(i.title)}</strong>${esc(i.text)}</button>`).join('');$('checks').querySelectorAll('[data-issue]').forEach(el=>el.onclick=()=>{const i=issues[+el.dataset.issue];selected=i.device?{kind:'device',id:i.device}:i.wire?{kind:'wire',id:i.wire}:null;render();if(i.device){const el=$('components').querySelector(`[data-id="${i.device}"]`);el?.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}})}
function render(){$('projectName').value=state.name;$('used').textContent=state.components.reduce((n,c)=>n+TYPES[c.type].width,0);$('undo').disabled=!history.length;$('redo').disabled=!future.length;renderBoard();renderInspector();renderCircuits();renderChecks();hint()}
$('selectMode').onclick=()=>setMode('select');$('wireMode').onclick=()=>setMode('wire');$('undo').onclick=()=>restore(history,future);$('redo').onclick=()=>restore(future,history);$('validate').onclick=()=>{checked=true;renderChecks();toast('Sprawdzono podstawowe reguły połączeń.')};$('toggleWires').onclick=()=>{showWires=!showWires;$('toggleWires').textContent=(showWires?'◉':'○')+' Przewody';renderBoard()};$('save').onclick=()=>{if(persist())toast('Projekt zapisany w tej przeglądarce.')} ;$('projectName').onchange=e=>change(()=>state.name=e.target.value.trim().slice(0,120)||'Nowy projekt');$('addCircuit').onclick=()=>change(()=>state.circuits.push({id:uid(),name:'Nowy obwód',device:'',power:0,cable:'3 × 2,5'}));$('reset').onclick=()=>{if(confirm('Utworzyć pusty projekt? Obecny układ można przywrócić przyciskiem Cofnij.'))change(()=>{state=fresh();selected=null;pending=null})};$('export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rozdzielnia-projekt.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Wyeksportowano projekt JSON.')};$('import').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2000000)throw Error('Plik jest za duży (maks. 2 MB).');const next=parse(JSON.parse(await f.text()));change(()=>{state=next;selected=null;pending=null});toast('Projekt zaimportowany.')}catch(e){toast('Import przerwany: '+e.message)}$('file').value=''};document.addEventListener('keydown',e=>{if(e.key==='Escape'){pending=null;selected=null;render()}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?restore(future,history):restore(history,future)}if(e.key==='Delete')removeSelected()});render();
